package com.example.modul4xml

import android.content.Intent
import android.os.Bundle
import androidx.appcompat.app.AppCompatActivity
import androidx.lifecycle.Lifecycle
import androidx.lifecycle.ViewModelProvider
import androidx.lifecycle.lifecycleScope
import androidx.lifecycle.repeatOnLifecycle
import androidx.recyclerview.widget.LinearLayoutManager
import com.example.modul4xml.databinding.ActivityMainBinding
import androidx.core.net.toUri
import timber.log.Timber

class MainActivity : AppCompatActivity() {

    private lateinit var binding: ActivityMainBinding
    private companion object {
        const val KEY_MAIN_SCROLL_Y = "key_main_scroll_y"
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivityMainBinding.inflate(layoutInflater)
        setContentView(binding.root)

        val viewModelFactory = CardViewModelFactory("MainScreen")
        val viewModel = ViewModelProvider(this, viewModelFactory)[CardViewModel::class.java]

        val adapter = CardAdapter(
            onDetailClick = viewModel::onDetailClick,
            onUrlClick = viewModel::onUrlClick
        )

        var latestItems: List<ContentCard> = emptyList()

        binding.rvFeatured.layoutManager = LinearLayoutManager(this, LinearLayoutManager.HORIZONTAL, false)
        binding.rvAllContent.layoutManager = LinearLayoutManager(this, LinearLayoutManager.VERTICAL, false)
        binding.rvFeatured.adapter = adapter
        binding.rvAllContent.adapter = adapter

        lifecycleScope.launch {
            repeatOnLifecycle(Lifecycle.State.STARTED) {
                launch {
                    viewModel.items.collect { items ->
                        latestItems = items
                        Timber.d("List submitted: count=%d", items.size)
                        adapter.updateData(items)
                    }
                }
                launch {
                    viewModel.event.collect { event ->
                        when (event) {
                            is UiEvent.OpenDetail -> {
                                val selected = latestItems.firstOrNull { it.id == event.cardId }
                                Timber.d("Navigate detail: id=%d, data=%s", event.cardId, selected)
                                val intent = Intent(this@MainActivity, DetailActivity::class.java).apply {
                                    putExtra("EXTRA_CARD_ID", event.cardId)
                                }
                                startActivity(intent)
                                viewModel.clearEvent()
                            }
                            is UiEvent.OpenUrl -> {
                                Timber.d("Open url: %s", event.url)
                                val browserIntent = Intent(Intent.ACTION_VIEW, event.url.toUri())
                                startActivity(browserIntent)
                                viewModel.clearEvent()
                            }
                            null -> Unit
                        }
                    }
                }
            }
        }

        val savedScrollY = savedInstanceState?.getInt(KEY_MAIN_SCROLL_Y, 0) ?: 0
        if (savedScrollY > 0) {
            binding.nsvMain.post {
                binding.nsvMain.scrollTo(0, savedScrollY)
            }
        }
    }

    override fun onSaveInstanceState(outState: Bundle) {
        outState.putInt(KEY_MAIN_SCROLL_Y, binding.nsvMain.scrollY)
        super.onSaveInstanceState(outState)
    }
}

